const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const lon = -49.053062;
    const lat = -1.593993;
    const aoi = ee.Geometry.Point([lon, lat]).buffer(100000); // 100 km
    const targetDate = ee.Date('2009-08-19');
    const dayStr = '2009-08-19';
    const directStart = ee.Date(dayStr);
    const directEnd = directStart.advance(1, 'day');

    // Helper to build Landsat 5/7 L2 collection over AOI and date range
    function ls57Collection(start, end) {
      const l5 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
        .filterBounds(aoi)
        .filterDate(start, end);
      const l7 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
        .filterBounds(aoi)
        .filterDate(start, end);
      return l5.merge(l7);
    }

    // 2. Data Acquisition & Check with recovery
    let col = ls57Collection(directStart, directEnd);
    let nDirect = await col.size().getInfo();
    console.log(`AOI radius: 100 km; area_km2: ${ (await aoi.area(1).divide(1e6).getInfo()).toFixed(1) }`);
    console.log(`L5/L7 on ${dayStr}: ${nDirect} images`);

    let usedStart = directStart;
    let usedEnd = directEnd;
    if (nDirect === 0) {
      // Expand to +/- 3 days
      usedStart = targetDate.advance(-3, 'day');
      usedEnd = targetDate.advance(4, 'day');
      col = ls57Collection(usedStart, usedEnd);
      const n3 = await col.size().getInfo();
      console.log(`Expanded window +/-3d images: ${n3}`);
      if (n3 === 0) {
        // Expand to +/- 10 days
        usedStart = targetDate.advance(-10, 'day');
        usedEnd = targetDate.advance(11, 'day');
        col = ls57Collection(usedStart, usedEnd);
        const n10 = await col.size().getInfo();
        console.log(`Expanded window +/-10d images: ${n10}`);
        if (n10 === 0) {
          console.log('No data found after expansions.');
          console.log('C1');
          return;
        }
      }
    }

    // Pick image closest to target date
    const sorted = col.map(function(img) {
      const diff = img.date().difference(targetDate, 'day').abs();
      return img.set('dateDiff', diff);
    }).sort('dateDiff');

    const img = ee.Image(sorted.first());
    const imgId = await img.get('SYSTEM_INDEX').getInfo();
    const imgDateStr = await img.date().format('YYYY-MM-dd').getInfo();
    const dateDiff = await img.get('dateDiff').getInfo();
    console.log(`Used window: ${await usedStart.format('YYYY-MM-dd').getInfo()} to ${await usedEnd.format('YYYY-MM-dd').getInfo()}`);
    console.log(`Chosen image: ${imgId} date=${imgDateStr} (Δdays=${dateDiff})`);

    // 3. Water/Land masks (JRC Yearly History 2009)
    const gsw2009 = ee.ImageCollection('JRC/GSW1_4/YearlyHistory')
      .filter(ee.Filter.eq('year', 2009))
      .first();
    if (gsw2009 === null) {
      console.log('JRC GSW 2009 not found.');
      console.log('C3');
      return;
    }
    const waterClass = ee.Image(gsw2009).select('waterClass');
    const waterMask = waterClass.eq(2).or(waterClass.eq(3)); // seasonal or permanent water
    const landMask = waterMask.not();

    // 4. Cloud presence from QA_PIXEL (cloud or dilated cloud)
    const qa = img.select('QA_PIXEL');
    const isFill = qa.bitwiseAnd(1).neq(0);
    const isDilated = qa.bitwiseAnd(1 << 1).neq(0);
    const isCloud = qa.bitwiseAnd(1 << 3).neq(0);
    const cloudish = isCloud.or(isDilated);
    const valid = isFill.not(); // count both clear and cloud as valid; exclude fill

    // 5. Area-weighted stats (km2) to avoid scale bias
    const areaKm2 = ee.Image.pixelArea().divide(1e6).reproject({crs: img.projection()});
    const validArea = areaKm2.updateMask(valid);
    const cloudArea = areaKm2.updateMask(valid.and(cloudish));

    const imgReduce = ee.Image.cat(
      cloudArea.updateMask(landMask).rename('cloud_land'),
      validArea.updateMask(landMask).rename('valid_land'),
      cloudArea.updateMask(waterMask).rename('cloud_water'),
      validArea.updateMask(waterMask).rename('valid_water')
    );

    const res = await imgReduce.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

    const clLand = res ? (res.cloud_land || 0) : null;
    const vlLand = res ? (res.valid_land || 0) : null;
    const clWater = res ? (res.cloud_water || 0) : null;
    const vlWater = res ? (res.valid_water || 0) : null;

    // 6. Validation & Final Answer
    if (clLand === null || vlLand === null || clWater === null || vlWater === null) {
      console.log('Reduction returned null.');
      console.log('C3');
      return;
    }

    const zeroLand = (vlLand === 0 || !isFinite(vlLand));
    const zeroWater = (vlWater === 0 || !isFinite(vlWater));
    if (zeroLand || zeroWater) {
      console.log(`Valid km2 Land: ${vlLand?.toFixed ? vlLand.toFixed(2) : vlLand}, Water: ${vlWater?.toFixed ? vlWater.toFixed(2) : vlWater}`);
      console.log('C2');
      return;
    }

    const pctLand = clLand / vlLand;
    const pctWater = clWater / vlWater;

    if (!isFinite(pctLand) || !isFinite(pctWater) || pctLand < 0 || pctWater < 0 || pctLand > 1.5 || pctWater > 1.5) {
      console.log('Invalid cloud fractions.');
      console.log('C3');
      return;
    }

    console.log(`Valid km2 Land: ${vlLand.toFixed(2)}, Water: ${vlWater.toFixed(2)}`);
    console.log(`Cloud km2 Land: ${clLand.toFixed(2)}, Water: ${clWater.toFixed(2)}`);
    console.log(`Cloud % Land: ${(pctLand*100).toFixed(1)}%, Water: ${(pctWater*100).toFixed(1)}%`);

    // Compare
    const answer = (pctLand > pctWater) ? 'A' : 'B';
    console.log(answer);
  } catch (err) {
    console.log(`Error: ${err.message}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
